    const registeredEmails = new Set();

    // ---------- DOM refs ----------
    const form = document.getElementById('signupForm');
    const nameInput = document.getElementById('nameInput');
    const emailInput = document.getElementById('emailInput');
    const submitBtn = document.getElementById('submitBtn');
    const seatsLeftDisplay = document.getElementById('seatsLeftDisplay');
    const messageArea = document.getElementById('messageArea');
    const messageText = document.getElementById('messageText');
    const resetBtn = document.getElementById('resetDemoBtn');

    // ---------- helpers ----------
    function updateSeatsLeft() {
      const left = TOTAL_SEATS - participants.length;
      seatsLeftDisplay.textContent = left;
      // disable form when full (but keep button enabled for possible error)
      if (left <= 0) {
        nameInput.disabled = true;
