      } else {
        nameInput.disabled = false;
        emailInput.disabled = false;
        submitBtn.disabled = false;
        // clear only if we were showing the full message
        if (messageArea.dataset.fullMessage === 'true') {
          hideMessage();
          messageArea.dataset.fullMessage = 'false';
        }
      }
    }

    function showMessage(text, type = 'info') {
      messageArea.style.display = 'flex';
      messageArea.className = `message ${type}`;  // type: success, error, info
      const iconSpan = messageArea.querySelector('.message-icon');
      if (type === 'success') iconSpan.textContent = '✅';
      else if (type === 'error') iconSpan.textContent = '⚠️';
      else iconSpan.textContent = 'ℹ️';
      messageText.textContent = text;
      messageArea.dataset.active = 'true';

      // mark if this is a full message
      if (text.includes('All 20 seats')) {
        messageArea.dataset.fullMessage = 'true';
      } else {
        messageArea.dataset.fullMessage = 'false';
      }
    }

    function hideMessage() {
      messageArea.style.display = 'none';
      messageArea.dataset.active = 'false';
      messageArea.dataset.fullMessage = 'false';
    }

    // ---------- ATOMIC booking operation ----------
    // This function is the ONLY way to add a participant.
