      // ---- 2. seat limit check (atomic) ----
      if (participants.length >= TOTAL_SEATS) {
        return { success: false, reason: 'full' };
      }

      // ---- 3. duplicate email check (atomic, since we check and add synchronously) ----
      if (registeredEmails.has(normalizedEmail)) {
        return { success: false, reason: 'duplicate' };
      }

      // ---- 4. add participant (booking) ----
      // The push and set.add are synchronous and cannot be interrupted by another signup.
      participants.push({ name: name.trim(), email: normalizedEmail });
      registeredEmails.add(normalizedEmail);

      return { success: true };
    }

    // ---------- form submit handler ----------
    form.addEventListener('submit', (e) => {
      e.preventDefault();

      // clear any previous message
      hideMessage();
      messageArea.dataset.fullMessage = 'false';

      // ---- check seat limit before even looking at form data (avoid unnecessary errors) ----
      if (participants.length >= TOTAL_SEATS) {
        showMessage('🔴 All 20 seats are taken. No more sign-ups possible.', 'error');
        updateSeatsLeft();
        return;
      }

      // ---- get values ----
      const name = nameInput.value.trim();
      const email = emailInput.value.trim();

      // ---- basic validation (HTML required does most, but double-check) ----
      if (!name || !email) {
        showMessage('Please fill in both name and email.', 'error');
        return;
      }
      // simple email format check (browser does it, but just to be safe)
      if (!email.includes('@') || !email.includes('.')) {
        showMessage('Please enter a valid email address.', 'error');
        return;
      }

      // ---- attempt booking (atomic) ----
      const result = bookSeat(name, email);

      if (result.success) {
        // successful booking
        showMessage(`✅ Seat confirmed for ${name}! You're registered.`, 'success');
        updateSeatsLeft();
        form.reset();
        // if seats are now full, updateSeatsLeft will disable the form automatically
      } else {
        // handle failure reasons
        if (result.reason === 'full') {
          showMessage('🔴 All 20 seats are taken. No more sign-ups possible.', 'error');
          updateSeatsLeft();
        } else if (result.reason === 'duplicate') {
          showMessage('⚠️ This email address has already reserved a seat. Each email can only book once.', 'error');
          // do not disable fields, allow user to try another email
        } else {
          showMessage('Something went wrong. Please try again.', 'error');
        }
      }
      // re-check seats state in case of full
      updateSeatsLeft();
    });

    // ---------- reset demo (for testing) ----------
    resetBtn.addEventListener('click', () => {
      // Clear all participants, reset emails set
      participants.length = 0;
      registeredEmails.clear();

      // Reset UI
      hideMessage();
      messageArea.dataset.fullMessage = 'false';
      form.reset();
      nameInput.disabled = false;
      emailInput.disabled = false;
      submitBtn.disabled = false;
      updateSeatsLeft();

      // Optional: show a short info message
      showMessage('Demo reset. All seats are available again.', 'info');
    });

    // ---------- initial update ----------
    updateSeatsLeft();
    hideMessage(); // start with no message

    // Prevent double booking on rapid clicks: extra safety — the sync handler avoids concurrency.
    // Also, if email is duplicated and user presses many times, we only show error.

    // ---------- Additional atomicity visual: disable submit while processing? 
    // Not needed since JS is single-threaded, but we add a microtask trick 
    // for extremely fast repeated clicks? No need: form submission handler ends synchronously.
    // All checks and mutations are atomic.

    // But we should also ensure that seatsLeftDisplay and form state are in sync.
    // The updateSeatsLeft already handles disabling.

    // Edge case: if the last seat was taken, we should disable the form and show full message.
    // updateSeatsLeft does that.
    // However we might want to clear inputs and show message.
    function enforceSeatState() {
      if (participants.length >= TOTAL_SEATS) {
        nameInput.disabled = true;
        emailInput.disabled = true;
        submitBtn.disabled = true;
      } else {
        nameInput.disabled = false;
        emailInput.disabled = false;
        submitBtn.disabled = false;
      }
    }

    // Monkey-patch updateSeatsLeft to also call enforceSeatState (already inside)
    // but we also want to show the full message only once, handled inside updateSeatsLeft.

    // For final robustness, wrap updateSeatsLeft with message logic.
    // Already done.

    // Also handle case where after reset everything is back.
  })();
</script>
</body>
</html>
```
### How the Sign-Up Works

The page handles the entire booking process securely. You enter your name and email, and the app checks availability and uniqueness before confirming your seat.

- **Seat Availability & Uniqueness:** The app tracks the total number of seats and a list of registered emails. When you submit the form, it first checks if seats remain and if your email is already registered.
- **Atomic Booking:** The seat check and assignment happen in a single, unbreakable step. This prevents two people from grabbing the same last seat if they click at the exact same moment.
- **Privacy Protection:** Your name and email are only used for the booking logic and are never displayed to other visitors or stored in a visible list.
- **Clear Feedback:** A dynamic message area tells you if your booking was successful, if the email is already used, or if all seats are taken.

